\set ON_ERROR_STOP on
begin;
set local role authenticated;set local request.jwt.claims='{"sub":"31000000-0000-0000-0000-000000000001","role":"authenticated"}';
select public.finalise_attendance_import('view_attendance_punch','2026-09-07','punch.xlsx',repeat('a',64),'[{"Person ID":"EMP-1","Person Name":"Employee","Punch Date":"09/07/2026","Attendance record":"09:00:01","Verify Type":"Fingerprint","TimeZone":"+08:00","Source":"DEVICE-A"},{"Person ID":"EMP-1","Person Name":"Employee","Punch Date":"09/07/2026","Attendance record":"18:30:00","Verify Type":"Fingerprint","TimeZone":"+08:00","Source":"DEVICE-A"}]'::jsonb);
select public.finalise_attendance_import('view_attendance_punch','2026-09-07','punch.xlsx',repeat('a',64),'[{"Person ID":"EMP-1","Punch Date":"09/07/2026","Attendance record":"09:00:01","TimeZone":"+08:00","Source":"DEVICE-A"},{"Person ID":"EMP-1","Punch Date":"09/07/2026","Attendance record":"18:30:00","TimeZone":"+08:00","Source":"DEVICE-A"}]'::jsonb);
do $$ declare result public.daily_attendance_results; begin select * into result from public.daily_attendance_results where is_current; if result.late_seconds<>1 or result.recognised_paid_seconds<>30599 then raise exception 'Exact-second calculation failed: late %, recognised %',result.late_seconds,result.recognised_paid_seconds; end if; if (select count(*) from public.attendance_import_batches)<>2 or (select count(*) from public.attendance_raw_punch_events)<>2 or (select count(*) from public.attendance_import_batch_events)<>4 then raise exception 'Idempotent import failed'; end if; perform public.recalculate_attendance_week(result.import_batch_id); if (select count(*) from public.daily_attendance_results)<>3 or (select count(*) from public.daily_attendance_results where is_current)<>1 then raise exception 'Immutable recalculation revision failed'; end if; select * into result from public.daily_attendance_results where is_current; perform public.adjust_attendance_result(result.id,jsonb_build_object('recognised_paid_seconds',30000),'Reviewed correction'); if (select count(*) from public.attendance_adjustments)<>1 or (select max(calculation_revision) from public.daily_attendance_results)<>4 then raise exception 'Adjustment history failed'; end if; perform public.lock_attendance_period('2026-09-07',null); begin select * into result from public.daily_attendance_results where is_current; perform public.adjust_attendance_result(result.id,jsonb_build_object('recognised_paid_seconds',29999),'Must fail'); raise exception 'Locked adjustment was accepted'; exception when others then if sqlerrm='Locked adjustment was accepted' then raise; end if; end; end $$;
reset role;
rollback;
